from robot.utils.robottime import timestr_to_secs

from .base import BaseInterface
from ..validators import IsString
from ..converter import to_int


class EthernetServiceOamInterface(BaseInterface):
    def start_service_oam_loopback(self, oam_ma_dn, ccm_remote_mac_addr, ccm_remote_mep_id, timeout=60, alias="default"):
        """Start service OAM loopback.

        :param string oam_ma_dn: oam_ma distname.
        :param string ccm_remote_mac_addr: ccm_remote mac address.
        :param integer ccm_remote_mep_id: ccm_remote_mep_id
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: dict
        :return: result of Loopback test
        """

        timeout = timestr_to_secs(timeout)
        IsString().check(oam_ma_dn)
        IsString().check(ccm_remote_mac_addr)
        ccm_remote_mep_id = to_int(ccm_remote_mep_id)
        parameters = {
            "oamMaDN": oam_ma_dn,
            "ccmRemoteMacAddr": ccm_remote_mac_addr,
            "ccmRemoteMepId": ccm_remote_mep_id

        }
        return self.store.get(alias).execute_procedure("startServiceOamLoopback", parameters, timeout)

    def start_service_oam_link_trace(self, oam_ma_dn, ccm_remote_mac_addr, ccm_remote_mep_id, timeout=60, alias="default"):
        """Start service OAM link trace.

        :param string oam_ma_dn: oam_ma distname.
        :param string ccm_remote_mac_addr: ccm_remote mac address.
        :param integer ccm_remote_mep_id: ccm_remote_mep_id
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: dict
        :return: result of Linktrace test
        """

        timeout = timestr_to_secs(timeout)
        IsString().check(oam_ma_dn)
        IsString().check(ccm_remote_mac_addr)
        ccm_remote_mep_id = to_int(ccm_remote_mep_id)
        parameters = {
            "oamMaDN": oam_ma_dn,
            "ccmRemoteMacAddr": ccm_remote_mac_addr,
            "ccmRemoteMepId": ccm_remote_mep_id

        }
        return self.store.get(alias).execute_procedure("startServiceOamLinkTrace", parameters, timeout)
